import json, sys, datetime

def ts(d):
    t = d.get('timestamp')
    if not t: return None
    return datetime.datetime.fromisoformat(t.replace('Z','+00:00'))

def short(s, n):
    s = ' '.join(str(s).split())
    return s if len(s) <= n else s[:n] + ' …'

path = sys.argv[1]
TOOLN = int(sys.argv[2]) if len(sys.argv) > 2 else 160
entries = []
for l in open(path):
    l = l.strip()
    if not l: continue
    try: entries.append(json.loads(l))
    except: pass

first = None
prev = None
out = []
for d in entries:
    t = ts(d)
    if t and first is None: first = t
    off = f"{(t-first).total_seconds():7.0f}" if t else "      ?"
    gap = ''
    if t and prev:
        g = (t-prev).total_seconds()
        if g >= 20: gap = f"  [+{g:.0f}s gap]"
    if t: prev = t
    typ = d.get('type')
    msg = d.get('message') or {}
    side = 'SIDE ' if d.get('isSidechain') else ''
    content = msg.get('content')
    if typ == 'user':
        if isinstance(content, str):
            out.append(f"{off} {side}USER: {short(content, 1200)}{gap}")
        elif isinstance(content, list):
            for c in content:
                if c.get('type') == 'text':
                    out.append(f"{off} {side}USER: {short(c['text'], 1200)}{gap}")
                elif c.get('type') == 'tool_result':
                    body = c.get('content')
                    if isinstance(body, list):
                        body = ' '.join(x.get('text','') for x in body if isinstance(x,dict))
                    err = 'ERR ' if c.get('is_error') else ''
                    n = 500 if c.get('is_error') else TOOLN
                    out.append(f"{off}   <-{err}res: {short(body, n)}{gap}")
    elif typ == 'assistant':
        for c in (content or []):
            if c.get('type') == 'text' and c.get('text','').strip():
                out.append(f"{off} {side}ASSIST: {short(c['text'], 900)}{gap}")
            elif c.get('type') == 'tool_use':
                out.append(f"{off}   ->{c.get('name')}: {short(json.dumps(c.get('input')), TOOLN)}{gap}")
print(f"# {path}\n# entries={len(entries)} span={(prev-first).total_seconds()/60:.1f} min  start={first}")
print('\n'.join(out))

